package main

import (
	"os"

	"github.com/ammmir/mcpie/cmd"
	"github.com/ammmir/mcpie/internal/output"
)

func main() {
	// Detect --json/-j before cobra runs so cobra-level errors (unknown
	// command, wrong arg count) are formatted the same way as RunE errors.
	jsonMode := false
	for _, arg := range os.Args[1:] {
		if arg == "--json" || arg == "-j" {
			jsonMode = true
			break
		}
	}

	if err := cmd.Execute(); err != nil {
		output.New(jsonMode, os.Stdout).PrintError(err)
		os.Exit(1)
	}
}
